-- ============================================================
-- FREPPA quiz migration: SSS 1 English, Mathematics,
-- Physics and Chemistry.
--
-- Generated by backend/migrate_production_quiz.js
-- Contains 497 questions across 4 subjects.
--
-- Safe to run more than once. Each step is guarded, so running
-- this twice does not duplicate subjects or questions.
--
--   mysql -u USER -p DBNAME < backend/migrate_production_quiz.sql
--
-- Or paste the whole file into the Railway SQL editor.
-- ============================================================

SET NAMES utf8mb4;

-- ------------------------------------------------------------
-- 1. Questions table
-- ------------------------------------------------------------

CREATE TABLE IF NOT EXISTS questions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    subject_id INT NOT NULL,
    question_text TEXT NOT NULL,
    option_a VARCHAR(255) NOT NULL,
    option_b VARCHAR(255) NOT NULL,
    option_c VARCHAR(255) NOT NULL,
    option_d VARCHAR(255) NOT NULL,
    correct_option ENUM('A','B','C','D') NOT NULL,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_by INT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE,
    FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL,
    INDEX idx_questions_subject (subject_id, is_active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 2. Subject: English Language (ENG201)
-- ------------------------------------------------------------

-- subjects.subject_code is UNIQUE, so IGNORE skips it if present.
-- teacher_id is left NULL: the student quiz list only requires a
-- subject in the student's own class that has questions.
INSERT IGNORE INTO subjects (subject_name, subject_code, class_id, teacher_id)
SELECT 'English Language', 'ENG201', c.id, NULL
  FROM classes c
 WHERE c.class_name = 'SSS 1';

