    UNION ALL SELECT 'In ''The patient nurse attended to him'', the word ''patient'' is a(n)' AS q, 'noun' AS a, 'conjunction' AS b, 'adverb' AS c, 'adjective' AS d, 'D' AS k
    UNION ALL SELECT 'Which of the following is a preposition?' AS q, 'Between' AS a, 'Although' AS b, 'Beautiful' AS c, 'Quickly' AS d, 'A' AS k
    UNION ALL SELECT 'The word ''Although'' in ''Although it rained, we still went out'' is a' AS q, 'pronoun' AS a, 'preposition' AS b, 'conjunction' AS c, 'adverb' AS d, 'C' AS k
    UNION ALL SELECT 'Which of the following is a proper noun?' AS q, 'City' AS a, 'River' AS b, 'Chair' AS c, 'Lagos' AS d, 'D' AS k
    UNION ALL SELECT 'In ''We visited Abeokuta last month'', the word ''Abeokuta'' is a' AS q, 'common noun' AS a, 'proper noun' AS b, 'collective noun' AS c, 'abstract noun' AS d, 'B' AS k
    UNION ALL SELECT 'Which of the following nouns is concrete?' AS q, 'Courage' AS a, 'Table' AS b, 'Love' AS c, 'Honesty' AS d, 'B' AS k
    UNION ALL SELECT '''Bread'' in ''We were given some bread and milk'' is used as a' AS q, 'collective noun' AS a, 'abstract noun' AS b, 'count noun' AS c, 'mass noun' AS d, 'D' AS k
    UNION ALL SELECT 'Which of the following sentences is exclamatory?' AS q, 'What a beautiful dress!' AS a, 'Where are you going?' AS b, 'Please sit down.' AS c, 'The bell has rung.' AS d, 'A' AS k
