  ) t ON 1 = 1
 WHERE s.subject_code = 'ENG201'
   AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.subject_id = s.id);

-- ------------------------------------------------------------
-- 8. Questions for MTH201 (118)
-- ------------------------------------------------------------

-- The NOT EXISTS guard means a subject that already has questions
-- is left untouched, so a re-run cannot duplicate the pool.
INSERT INTO questions
    (subject_id, question_text, option_a, option_b, option_c, option_d, correct_option)
SELECT s.id, t.q, t.a, t.b, t.c, t.d, t.k
  FROM subjects s
  JOIN (
    SELECT 'What is the place value of 7 in 4,782?' AS q, '700' AS a, '7,000' AS b, '70' AS c, '70,000' AS d, 'B' AS k
    UNION ALL SELECT 'What is the place value of 4 in 4,782?' AS q, '4,000' AS a, '40' AS b, '400' AS c, '4' AS d, 'C' AS k
    UNION ALL SELECT 'What is the place value of 8 in 4,782?' AS q, '80' AS a, '8' AS b, '80,000' AS c, '800' AS d, 'A' AS k
    UNION ALL SELECT 'Round 6,743 to the nearest hundred.' AS q, '6,740' AS a, '6,800' AS b, '6,750' AS c, '6,700' AS d, 'D' AS k
    UNION ALL SELECT 'Round 8,451 to the nearest hundred.' AS q, '8,400' AS a, '8,460' AS b, '8,450' AS c, '8,500' AS d, 'D' AS k
    UNION ALL SELECT 'Round 2,318 to the nearest ten.' AS q, '2,310' AS a, '2,300' AS b, '2,330' AS c, '2,320' AS d, 'D' AS k
    UNION ALL SELECT 'What is the value of 5 raised to the power of 3?' AS q, '125' AS a, '15' AS b, '25' AS c, '50' AS d, 'A' AS k
    UNION ALL SELECT 'What is the value of the square root of 144?' AS q, '14' AS a, '16' AS b, '12' AS c, '18' AS d, 'C' AS k
