  ) t ON 1 = 1
 WHERE s.subject_code = 'MTH201'
   AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.subject_id = s.id);

-- ------------------------------------------------------------
-- 9. Questions for PHY201 (140)
-- ------------------------------------------------------------

-- The NOT EXISTS guard means a subject that already has questions
-- is left untouched, so a re-run cannot duplicate the pool.
INSERT INTO questions
    (subject_id, question_text, option_a, option_b, option_c, option_d, correct_option)
SELECT s.id, t.q, t.a, t.b, t.c, t.d, t.k
  FROM subjects s
  JOIN (
    SELECT 'What is the SI unit of force?' AS q, 'Joule' AS a, 'Watt' AS b, 'Newton' AS c, 'Pascal' AS d, 'C' AS k
    UNION ALL SELECT 'What is the SI unit of energy?' AS q, 'Watt' AS a, 'Pascal' AS b, 'Joule' AS c, 'Newton' AS d, 'C' AS k
    UNION ALL SELECT 'What is the SI unit of power?' AS q, 'Watt' AS a, 'Joule' AS b, 'Newton' AS c, 'Ampere' AS d, 'A' AS k
    UNION ALL SELECT 'What is the SI unit of pressure?' AS q, 'Joule' AS a, 'Newton' AS b, 'Watt' AS c, 'Pascal' AS d, 'D' AS k
    UNION ALL SELECT 'What is the SI unit of electric current?' AS q, 'Volt' AS a, 'Ohm' AS b, 'Watt' AS c, 'Ampere' AS d, 'D' AS k
    UNION ALL SELECT 'What is the SI unit of electric charge?' AS q, 'Tesla' AS a, 'Volt' AS b, 'Ohm' AS c, 'Coulomb' AS d, 'D' AS k
    UNION ALL SELECT 'What is the SI unit of electric potential difference?' AS q, 'Volt' AS a, 'Ohm' AS b, 'Coulomb' AS c, 'Watt' AS d, 'A' AS k
    UNION ALL SELECT 'What is the SI unit of mass?' AS q, 'Newton' AS a, 'Pound' AS b, 'Kilogram' AS c, 'Gram' AS d, 'C' AS k
    UNION ALL SELECT 'Which of these is a vector quantity?' AS q, 'Speed' AS a, 'Distance' AS b, 'Mass' AS c, 'Displacement' AS d, 'D' AS k
    UNION ALL SELECT 'Which of these is a scalar quantity?' AS q, 'Velocity' AS a, 'Displacement' AS b, 'Force' AS c, 'Acceleration' AS d, 'B' AS k
    UNION ALL SELECT 'What is the SI unit of displacement?' AS q, 'Metre per second' AS a, 'Metre' AS b, 'Second' AS c, 'Kilometre per hour' AS d, 'B' AS k
    UNION ALL SELECT 'What is the SI unit of velocity?' AS q, 'Kilogram per second' AS a, 'Metre' AS b, 'Second' AS c, 'Metre per second' AS d, 'D' AS k
    UNION ALL SELECT 'What is the SI unit of acceleration?' AS q, 'Metre per second squared' AS a, 'Metre per second' AS b, 'Second squared' AS c, 'Kilogram per metre' AS d, 'A' AS k
    UNION ALL SELECT 'Speed is measured in' AS q, 'seconds' AS a, 'metres per second squared' AS b, 'metres' AS c, 'metres per second' AS d, 'D' AS k
    UNION ALL SELECT 'Distance is a' AS q, 'scalar quantity' AS a, 'vector quantity' AS b, 'dimension' AS c, 'unit' AS d, 'A' AS k
    UNION ALL SELECT 'A body at rest remains at rest unless acted upon by an unbalanced' AS q, 'mass' AS a, 'weight' AS b, 'moment' AS c, 'force' AS d, 'D' AS k
    UNION ALL SELECT 'Newton''s first law of motion is also known as the law of' AS q, 'acceleration' AS a, 'inertia' AS b, 'action and reaction' AS c, 'gravitation' AS d, 'B' AS k
    UNION ALL SELECT 'Newton''s second law of motion relates force to' AS q, 'mass and acceleration' AS a, 'momentum only' AS b, 'action and reaction' AS c, 'inertia' AS d, 'A' AS k
    UNION ALL SELECT 'Newton''s third law of motion is the law of' AS q, 'inertia' AS a, 'acceleration' AS b, 'action and reaction' AS c, 'gravitation' AS d, 'C' AS k
    UNION ALL SELECT 'Which of these is a unit of impulse?' AS q, 'Newton second' AS a, 'Joule' AS b, 'Watt' AS c, 'Newton' AS d, 'A' AS k
    UNION ALL SELECT 'Impulse is equal to' AS q, 'force multiplied by mass' AS a, 'force multiplied by time' AS b, 'mass multiplied by velocity' AS c, 'energy divided by time' AS d, 'B' AS k
    UNION ALL SELECT 'Momentum is the product of mass and' AS q, 'velocity' AS a, 'acceleration' AS b, 'force' AS c, 'time' AS d, 'A' AS k
    UNION ALL SELECT 'A force of 10 N acting on a mass of 5 kg produces an acceleration of' AS q, '15 metre per second squared' AS a, '50 metre per second squared' AS b, '2 metre per second squared' AS c, '0.5 metre per second squared' AS d, 'C' AS k
    UNION ALL SELECT 'Weight is the product of mass and' AS q, 'friction' AS a, 'velocity' AS b, 'acceleration due to gravity' AS c, 'force' AS d, 'C' AS k
    UNION ALL SELECT 'What is the approximate value of acceleration due to gravity near the surface of the earth?' AS q, '10.8 metre per second squared' AS a, '98 metre per second squared' AS b, '0.98 metre per second squared' AS c, '9.8 metre per second squared' AS d, 'D' AS k
    UNION ALL SELECT 'Which of these is a contact force?' AS q, 'Magnetic force' AS a, 'Friction' AS b, 'Electrostatic force' AS c, 'Gravitational force' AS d, 'B' AS k
    UNION ALL SELECT 'Friction is a force that opposes' AS q, 'motion' AS a, 'weight' AS b, 'gravity' AS c, 'electricity' AS d, 'A' AS k
    UNION ALL SELECT 'Which of these is not a contact force?' AS q, 'Tension' AS a, 'Normal reaction' AS b, 'Gravitational force' AS c, 'Friction' AS d, 'C' AS k
    UNION ALL SELECT 'Work is done when a force moves a body through a' AS q, 'time' AS a, 'distance' AS b, 'mass' AS c, 'velocity' AS d, 'B' AS k
    UNION ALL SELECT 'What is the SI unit of work?' AS q, 'Pascal' AS a, 'Newton' AS b, 'Joule' AS c, 'Watt' AS d, 'C' AS k
    UNION ALL SELECT 'Work equals force multiplied by' AS q, 'time' AS a, 'distance in the direction of the force' AS b, 'mass' AS c, 'speed' AS d, 'B' AS k
    UNION ALL SELECT 'Power is the rate of doing work and is measured in' AS q, 'newton' AS a, 'pascal' AS b, 'joule' AS c, 'watt' AS d, 'D' AS k
