 WHERE s.subject_code = 'PHY201'
   AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.subject_id = s.id);

-- ------------------------------------------------------------
-- 10. Questions for CHM201 (135)
-- ------------------------------------------------------------

-- The NOT EXISTS guard means a subject that already has questions
-- is left untouched, so a re-run cannot duplicate the pool.
INSERT INTO questions
    (subject_id, question_text, option_a, option_b, option_c, option_d, correct_option)
SELECT s.id, t.q, t.a, t.b, t.c, t.d, t.k
  FROM subjects s
  JOIN (
    SELECT 'What is the chemical symbol for gold?' AS q, 'Ag' AS a, 'Gd' AS b, 'Au' AS c, 'Go' AS d, 'C' AS k
    UNION ALL SELECT 'What is the chemical symbol for silver?' AS q, 'Si' AS a, 'Sv' AS b, 'Ag' AS c, 'Au' AS d, 'C' AS k
    UNION ALL SELECT 'What is the chemical symbol for iron?' AS q, 'Fe' AS a, 'Ir' AS b, 'In' AS c, 'I' AS d, 'A' AS k
    UNION ALL SELECT 'What is the chemical symbol for sodium?' AS q, 'No' AS a, 'Sd' AS b, 'Sm' AS c, 'Na' AS d, 'D' AS k
    UNION ALL SELECT 'What is the chemical symbol for potassium?' AS q, 'Po' AS a, 'Pt' AS b, 'P' AS c, 'K' AS d, 'D' AS k
    UNION ALL SELECT 'What is the chemical symbol for calcium?' AS q, 'Cm' AS a, 'Cl' AS b, 'C' AS c, 'Ca' AS d, 'D' AS k
    UNION ALL SELECT 'What is the chemical symbol for oxygen?' AS q, 'O' AS a, 'Ox' AS b, 'Oxy' AS c, 'Om' AS d, 'A' AS k
    UNION ALL SELECT 'What is the chemical symbol for hydrogen?' AS q, 'Hg' AS a, 'He' AS b, 'H' AS c, 'Hy' AS d, 'C' AS k
    UNION ALL SELECT 'What is the chemical symbol for carbon?' AS q, 'Ca' AS a, 'Cb' AS b, 'Cr' AS c, 'C' AS d, 'D' AS k
    UNION ALL SELECT 'What is the chemical symbol for nitrogen?' AS q, 'Ni' AS a, 'N' AS b, 'Nt' AS c, 'Ny' AS d, 'B' AS k
    UNION ALL SELECT 'What is the chemical symbol for copper?' AS q, 'Cp' AS a, 'Cu' AS b, 'Cr' AS c, 'Co' AS d, 'B' AS k
    UNION ALL SELECT 'What is the chemical symbol for lead?' AS q, 'L' AS a, 'Ld' AS b, 'Pd' AS c, 'Pb' AS d, 'D' AS k
    UNION ALL SELECT 'What is the chemical symbol for chlorine?' AS q, 'Cl' AS a, 'Ch' AS b, 'C' AS c, 'Cn' AS d, 'A' AS k
    UNION ALL SELECT 'What is the chemical symbol for helium?' AS q, 'Hm' AS a, 'H' AS b, 'Hl' AS c, 'He' AS d, 'D' AS k
    UNION ALL SELECT 'What is the chemical symbol for calcium oxide?' AS q, 'CaO' AS a, 'CaC' AS b, 'CaO2' AS c, 'Ca' AS d, 'A' AS k
    UNION ALL SELECT 'What is the chemical symbol for sodium chloride?' AS q, 'SmCl' AS a, 'NaC' AS b, 'NaCl2' AS c, 'NaCl' AS d, 'D' AS k
