    UNION ALL SELECT 'Which of these is the maximum number of electrons in the second shell?' AS q, '8' AS a, '2' AS b, '6' AS c, '18' AS d, 'A' AS k
    UNION ALL SELECT 'Which of these is the maximum number of electrons in the third shell?' AS q, '18' AS a, '2' AS b, '6' AS c, '8' AS d, 'A' AS k
    UNION ALL SELECT 'The number of electrons in an atom is equal to the number of its' AS q, 'neutrons' AS a, 'protons' AS b, 'protons and neutrons' AS c, 'nuclei' AS d, 'B' AS k
    UNION ALL SELECT 'An atom becomes a cation when it' AS q, 'loses neutrons' AS a, 'gains electrons' AS b, 'loses electrons' AS c, 'gains protons' AS d, 'C' AS k
    UNION ALL SELECT 'An atom becomes an anion when it' AS q, 'loses electrons' AS a, 'gains electrons' AS b, 'loses protons' AS c, 'gains neutrons' AS d, 'B' AS k
    UNION ALL SELECT 'The loss of electrons from an atom is called' AS q, 'oxidation' AS a, 'displacement' AS b, 'combustion' AS c, 'reduction' AS d, 'A' AS k
    UNION ALL SELECT 'The gain of electrons by an atom is called' AS q, 'oxidation' AS a, 'condensation' AS b, 'reduction' AS c, 'neutralisation' AS d, 'C' AS k
    UNION ALL SELECT 'A substance made up of two or more elements chemically combined is called a' AS q, 'mixture' AS a, 'element' AS b, 'mixture of gases' AS c, 'compound' AS d, 'D' AS k
    UNION ALL SELECT 'A substance that cannot be broken down into simpler substances is called a' AS q, 'compound' AS a, 'mixture' AS b, 'element' AS c, 'solution' AS d, 'C' AS k
    UNION ALL SELECT 'A physical mixture of substances is different from a compound because a mixture' AS q, 'cannot be separated' AS a, 'can be separated by physical means' AS b, 'is always a gas' AS c, 'is always a solid' AS d, 'B' AS k
    UNION ALL SELECT 'Which of these is a physical change?' AS q, 'Burning magnesium' AS a, 'Melting wax' AS b, 'Rusting iron' AS c, 'Adding acid to a metal carbonate' AS d, 'B' AS k
    UNION ALL SELECT 'Which of these is a chemical change?' AS q, 'Dissolving sugar in water' AS a, 'Rusting iron' AS b, 'Breaking glass' AS c, 'Melting ice' AS d, 'B' AS k
    UNION ALL SELECT 'Which of these is a reversible physical change?' AS q, 'Burning paper' AS a, 'Rusting iron' AS b, 'Freezing water' AS c, 'Burning magnesium' AS d, 'C' AS k
    UNION ALL SELECT 'The formation of new substances during a chemical reaction is accompanied by' AS q, 'a colour change only' AS a, 'a change in state only' AS b, 'a change in size' AS c, 'an energy change' AS d, 'D' AS k
    UNION ALL SELECT 'In a chemical reaction the total mass of products is equal to the total mass of the' AS q, 'catalyst' AS a, 'solvent' AS b, 'reactants' AS c, 'atmosphere' AS d, 'C' AS k
    UNION ALL SELECT 'This law states that matter is neither created nor destroyed in a chemical reaction. It is the law of' AS q, 'constant composition' AS a, 'conservation of mass' AS b, 'definite proportions' AS c, 'multiple proportions' AS d, 'B' AS k
    UNION ALL SELECT 'The law of constant composition states that a compound always contains the same' AS q, 'volume of gas' AS a, 'number of atoms' AS b, 'elements in the same proportion by mass' AS c, 'mass of catalyst' AS d, 'C' AS k
    UNION ALL SELECT 'A substance added to a chemical reaction to speed it up without being consumed is a' AS q, 'reagent' AS a, 'catalyst' AS b, 'product' AS c, 'solvent' AS d, 'B' AS k
    UNION ALL SELECT 'A substance that dissolves in a liquid to form a solution is the' AS q, 'solute' AS a, 'solvent' AS b, 'solution' AS c, 'suspension' AS d, 'A' AS k
    UNION ALL SELECT 'The liquid in a solution is called the' AS q, 'solute' AS a, 'colloid' AS b, 'solvent' AS c, 'suspension' AS d, 'C' AS k
    UNION ALL SELECT 'A solution in which the solute dissolves completely is described as' AS q, 'unsaturated' AS a, 'concentrated' AS b, 'saturated' AS c, 'dilute' AS d, 'C' AS k
