    UNION ALL SELECT 'A suspension is different from a solution because the particles of a suspension' AS q, 'never settle' AS a, 'are dissolved' AS b, 'are invisible' AS c, 'settle on standing' AS d, 'D' AS k
    UNION ALL SELECT 'Which of these is an example of a solution?' AS q, 'Oil in water' AS a, 'Chalk in water' AS b, 'Salt in water' AS c, 'Sand in water' AS d, 'C' AS k
    UNION ALL SELECT 'Which of these is a heterogeneous mixture?' AS q, 'Salt in water' AS a, 'Sand in water' AS b, 'Sugar in water' AS c, 'Air' AS d, 'B' AS k
    UNION ALL SELECT 'Which of these is a colloid?' AS q, 'Milk' AS a, 'Salt solution' AS b, 'Sugar solution' AS c, 'Mud' AS d, 'A' AS k
    UNION ALL SELECT 'The separation of an insoluble solid from a liquid is done by' AS q, 'evaporation' AS a, 'filteration' AS b, 'distillation' AS c, 'crystallisation' AS d, 'B' AS k
