    UNION ALL SELECT 'A separating funnel is used to separate two immiscible liquids of different' AS q, 'colours' AS a, 'boiling points' AS b, 'densities' AS c, 'solubilities' AS d, 'C' AS k
    UNION ALL SELECT 'The process of changing a gas directly into a liquid is called' AS q, 'sublimation' AS a, 'melting' AS b, 'deposition' AS c, 'condensation' AS d, 'D' AS k
    UNION ALL SELECT 'The process of changing a solid directly into a gas is called' AS q, 'condensation' AS a, 'sublimation' AS b, 'melting' AS c, 'evaporation' AS d, 'B' AS k
    UNION ALL SELECT 'The process of changing a liquid into a solid is called' AS q, 'evaporation' AS a, 'boiling' AS b, 'melting' AS c, 'freezing' AS d, 'D' AS k
    UNION ALL SELECT 'The change of state from liquid to gas is called' AS q, 'condensation' AS a, 'sublimation' AS b, 'freezing' AS c, 'evaporation' AS d, 'D' AS k
    UNION ALL SELECT 'Which of these is an example of sublimation?' AS q, 'Water boiling' AS a, 'Iron rusting' AS b, 'Camphor turning to vapour' AS c, 'Ice melting' AS d, 'C' AS k
    UNION ALL SELECT 'The boiling point of water is' AS q, '0 degrees celsius' AS a, '50 degrees celsius' AS b, '212 degrees celsius' AS c, '100 degrees celsius' AS d, 'D' AS k
    UNION ALL SELECT 'The melting point of ice is' AS q, '0 degrees celsius' AS a, '37 degrees celsius' AS b, '100 degrees celsius' AS c, '-100 degrees celsius' AS d, 'A' AS k
    UNION ALL SELECT 'Water is a universal solvent because it' AS q, 'is cheap' AS a, 'dissolves a large number of substances' AS b, 'is a liquid' AS c, 'is colourless' AS d, 'B' AS k
    UNION ALL SELECT 'The solubility of a substance is the maximum amount that dissolves in a given quantity of solvent at a given' AS q, 'concentration' AS a, 'pressure' AS b, 'volume' AS c, 'temperature' AS d, 'D' AS k
    UNION ALL SELECT 'The solubility of most solids in water increases as the' AS q, 'temperature increases' AS a, 'temperature decreases' AS b, 'pressure decreases' AS c, 'volume increases' AS d, 'A' AS k
    UNION ALL SELECT 'Which of these factors does not affect the solubility of a solid in water?' AS q, 'Shape of the container' AS a, 'Nature of the solute' AS b, 'Nature of the solvent' AS c, 'Temperature' AS d, 'A' AS k
    UNION ALL SELECT 'A solution containing an equal amount of solute and solvent by mass is called' AS q, 'dilute' AS a, 'concentrated' AS b, 'saturated' AS c, 'molecular' AS d, 'B' AS k
    UNION ALL SELECT 'The strength of an acid depends mainly on the' AS q, 'amount of acid used' AS a, 'concentration of hydrogen ions' AS b, 'colour of the acid' AS c, 'container size' AS d, 'B' AS k
    UNION ALL SELECT 'An acid turns blue litmus paper' AS q, 'blue' AS a, 'red' AS b, 'green' AS c, 'orange' AS d, 'B' AS k
    UNION ALL SELECT 'A base turns red litmus paper' AS q, 'violet' AS a, 'blue' AS b, 'red' AS c, 'green' AS d, 'B' AS k
    UNION ALL SELECT 'What is the pH of a neutral solution at room temperature?' AS q, '0' AS a, '10' AS b, '14' AS c, '7' AS d, 'D' AS k
    UNION ALL SELECT 'What is the pH of a strongly acidic solution?' AS q, 'Above 7' AS a, 'Exactly 14' AS b, 'Below 7' AS c, 'Exactly 7' AS d, 'C' AS k
    UNION ALL SELECT 'What is the pH of a strongly alkaline solution?' AS q, 'Below 7' AS a, 'Exactly 7' AS b, 'Above 7' AS c, 'Exactly 0' AS d, 'C' AS k
    UNION ALL SELECT 'What happens to the pH of an acid when it is diluted with water?' AS q, 'It decreases' AS a, 'It increases' AS b, 'It stays the same' AS c, 'It becomes 7' AS d, 'B' AS k
    UNION ALL SELECT 'A solution of pH 3 is described as' AS q, 'alkaline' AS a, 'acidic' AS b, 'neutral' AS c, 'amphoteric' AS d, 'B' AS k
    UNION ALL SELECT 'Which of these is a common alkali?' AS q, 'Nitric acid' AS a, 'Hydrochloric acid' AS b, 'Sodium hydroxide' AS c, 'Sulphuric acid' AS d, 'C' AS k
    UNION ALL SELECT 'Which of these is a mineral acid?' AS q, 'Hydrochloric acid' AS a, 'Sodium hydroxide' AS b, 'Ammonia solution' AS c, 'Calcium hydroxide' AS d, 'A' AS k
    UNION ALL SELECT 'Neutralisation is the reaction of an acid with a' AS q, 'salt' AS a, 'base' AS b, 'gas' AS c, 'metal' AS d, 'B' AS k
    UNION ALL SELECT 'The product of the neutralisation of a base with an acid is a' AS q, 'gas only' AS a, 'metal oxide only' AS b, 'alkali only' AS c, 'salt and water' AS d, 'D' AS k
    UNION ALL SELECT 'Which of these is a common household acid?' AS q, 'Sodium hydroxide' AS a, 'Calcium hydroxide' AS b, 'Ammonia' AS c, 'Citric acid' AS d, 'D' AS k
    UNION ALL SELECT 'Which of these is a common use of alkalis?' AS q, 'Making soap' AS a, 'Fertilising crops' AS b, 'Making paper' AS c, 'All of the above' AS d, 'D' AS k
    UNION ALL SELECT 'A salt is formed when' AS q, 'all of the above' AS a, 'an acid reacts with a carbonate' AS b, 'an acid reacts with a base' AS c, 'an acid reacts with a metal' AS d, 'A' AS k
    UNION ALL SELECT 'Which of these is an acidic salt?' AS q, 'Sodium chloride' AS a, 'Ammonium nitrate' AS b, 'Calcium carbonate' AS c, 'Potassium hydroxide' AS d, 'B' AS k
    UNION ALL SELECT 'What kind of reaction occurs when zinc reacts with dilute hydrochloric acid?' AS q, 'Combination' AS a, 'Decomposition' AS b, 'Displacement' AS c, 'Neutralisation' AS d, 'C' AS k
    UNION ALL SELECT 'What kind of reaction occurs when hydrogen burns in oxygen?' AS q, 'Displacement' AS a, 'Decomposition' AS b, 'Neutralisation' AS c, 'Combination' AS d, 'D' AS k
    UNION ALL SELECT 'What kind of reaction occurs when calcium carbonate is heated strongly?' AS q, 'Combination' AS a, 'Decomposition' AS b, 'Displacement' AS c, 'Neutralisation' AS d, 'B' AS k
    UNION ALL SELECT 'Which of these reactions is a displacement reaction?' AS q, 'Magnesium plus oxygen forms magnesium oxide' AS a, 'Sodium plus water forms sodium hydroxide and hydrogen' AS b, 'Calcium carbonate forms calcium oxide and carbon dioxide' AS c, 'Hydrogen plus oxygen forms water' AS d, 'B' AS k
    UNION ALL SELECT 'A substance that speeds up a chemical reaction without being used up is a' AS q, 'reactant' AS a, 'solvent' AS b, 'product' AS c, 'catalyst' AS d, 'D' AS k
    UNION ALL SELECT 'The substance formed after a chemical reaction is the' AS q, 'product' AS a, 'reactant' AS b, 'catalyst' AS c, 'solvent' AS d, 'A' AS k
    UNION ALL SELECT 'The substance present before a chemical reaction is the' AS q, 'reactant' AS a, 'residue' AS b, 'catalyst' AS c, 'product' AS d, 'A' AS k
    UNION ALL SELECT 'Which of these changes is a redox reaction?' AS q, 'Dissolution of sugar in water' AS a, 'Melting of ice' AS b, 'Breaking of glass' AS c, 'Combustion of magnesium' AS d, 'D' AS k
    UNION ALL SELECT 'During combustion, a substance reacts with' AS q, 'water' AS a, 'oxygen' AS b, 'carbon dioxide' AS c, 'nitrogen' AS d, 'B' AS k
    UNION ALL SELECT 'Complete combustion of a hydrocarbon produces' AS q, 'carbon dioxide and water' AS a, 'carbon monoxide and hydrogen' AS b, 'nitrogen and oxygen' AS c, 'water only' AS d, 'A' AS k
    UNION ALL SELECT 'The flame of burning magnesium is' AS q, 'bright white' AS a, 'invisible' AS b, 'blue' AS c, 'orange' AS d, 'A' AS k
    UNION ALL SELECT 'A common test for carbon dioxide gas is to bubble it through' AS q, 'starch solution' AS a, 'limewater' AS b, 'copper sulphate solution' AS c, 'silver nitrate solution' AS d, 'B' AS k
    UNION ALL SELECT 'Carbon dioxide turns limewater' AS q, 'white then milky' AS a, 'black' AS b, 'pink' AS c, 'blue' AS d, 'A' AS k
    UNION ALL SELECT 'Which gas turns limewater milky?' AS q, 'Carbon dioxide' AS a, 'Oxygen' AS b, 'Hydrogen' AS c, 'Nitrogen' AS d, 'A' AS k
    UNION ALL SELECT 'A common test for hydrogen gas is to bring a burning splint near it and it' AS q, 'burns with a pop sound' AS a, 'glows red' AS b, 'rekindles a glowing splint' AS c, 'turns limewater milky' AS d, 'A' AS k
    UNION ALL SELECT 'A burning splint rekindled in a gas identifies the gas as' AS q, 'oxygen' AS a, 'hydrogen' AS b, 'carbon dioxide' AS c, 'nitrogen' AS d, 'A' AS k
    UNION ALL SELECT 'Oxygen is needed for' AS q, 'digestion only' AS a, 'respiration only' AS b, 'combustion only' AS c, 'respiration and combustion' AS d, 'D' AS k
    UNION ALL SELECT 'Which of these gases is most abundant in air?' AS q, 'Oxygen' AS a, 'Carbon dioxide' AS b, 'Nitrogen' AS c, 'Hydrogen' AS d, 'C' AS k
    UNION ALL SELECT 'Which of these is NOT a main component of air?' AS q, 'Hydrogen' AS a, 'Oxygen' AS b, 'Argon' AS c, 'Nitrogen' AS d, 'A' AS k
    UNION ALL SELECT 'Which gas is used in the Haber process to make ammonia?' AS q, 'Carbon dioxide' AS a, 'Hydrogen' AS b, 'Nitrogen' AS c, 'Oxygen' AS d, 'C' AS k
    UNION ALL SELECT 'Which gas is used in the manufacture of hydrochloric acid?' AS q, 'Oxygen' AS a, 'Chlorine' AS b, 'Hydrogen' AS c, 'Nitrogen' AS d, 'B' AS k
    UNION ALL SELECT 'Which gas is used to fill balloons?' AS q, 'Carbon dioxide' AS a, 'Hydrogen' AS b, 'Helium' AS c, 'Nitrogen' AS d, 'C' AS k
    UNION ALL SELECT 'What is the main gas responsible for the greenhouse effect?' AS q, 'Carbon dioxide' AS a, 'Hydrogen' AS b, 'Oxygen' AS c, 'Nitrogen' AS d, 'A' AS k
    UNION ALL SELECT 'Which of these increases the concentration of carbon dioxide in the atmosphere?' AS q, 'Planting trees' AS a, 'Using solar energy' AS b, 'Recycling waste' AS c, 'Burning fossil fuels' AS d, 'D' AS k
    UNION ALL SELECT 'Which of these is NOT a chemical change?' AS q, 'Burning wood' AS a, 'Souring milk' AS b, 'Dissolving sugar in water' AS c, 'Rusting a nail' AS d, 'C' AS k
    UNION ALL SELECT 'A chemical reaction that releases heat to the surroundings is' AS q, 'endothermic' AS a, 'reversible' AS b, 'spontaneous' AS c, 'exothermic' AS d, 'D' AS k
    UNION ALL SELECT 'A chemical reaction that absorbs heat from the surroundings is' AS q, 'exothermic' AS a, 'complete' AS b, 'endothermic' AS c, 'combustion' AS d, 'C' AS k
    UNION ALL SELECT 'Which of these is an endothermic process?' AS q, 'Burning of a candle' AS a, 'Rusting of iron' AS b, 'Burning of wood' AS c, 'Melting of ice' AS d, 'D' AS k
    UNION ALL SELECT 'Which of these is an exothermic process?' AS q, 'Evaporation of water' AS a, 'Melting of ice' AS b, 'Dissolving ammonium nitrate' AS c, 'Burning of a candle' AS d, 'D' AS k
    UNION ALL SELECT 'What quantity of heat is required to raise the temperature of 1 kg of a substance by 1 degree celsius called?' AS q, 'Latent heat' AS a, 'Thermal capacity' AS b, 'Specific heat capacity' AS c, 'Molar heat' AS d, 'C' AS k
    UNION ALL SELECT 'The specific heat capacity of water is approximately' AS q, '4.2 joules per kilogram per degree celsius' AS a, '4200 kilojoules per kilogram per degree celsius' AS b, '0.24 joules per kilogram per degree celsius' AS c, '1 joule per kilogram per degree celsius' AS d, 'A' AS k
    UNION ALL SELECT 'Which metal has the highest specific heat capacity?' AS q, 'Iron' AS a, 'Aluminium' AS b, 'Copper' AS c, 'Lead' AS d, 'B' AS k
    UNION ALL SELECT 'Water has a high specific heat capacity which means that water' AS q, 'heats up quickly' AS a, 'heats up slowly and can store a lot of heat' AS b, 'does not absorb heat' AS c, 'loses heat instantly' AS d, 'B' AS k
    UNION ALL SELECT 'Heat is a form of' AS q, 'energy' AS a, 'power' AS b, 'force' AS c, 'matter' AS d, 'A' AS k
    UNION ALL SELECT 'The SI unit of heat is' AS q, 'degree celsius' AS a, 'calorie' AS b, 'kelvin' AS c, 'joule' AS d, 'D' AS k
    UNION ALL SELECT 'One calorie is equivalent to how many joules?' AS q, '4.2 J' AS a, '0.42 J' AS b, '42 J' AS c, '420 J' AS d, 'A' AS k
    UNION ALL SELECT 'What is the term for the direct transfer of heat from one body to another without a medium?' AS q, 'Radiation' AS a, 'Convection current' AS b, 'Conduction' AS c, 'Convection' AS d, 'C' AS k
    UNION ALL SELECT 'Metals are good conductors of heat because they have' AS q, 'free electrons' AS a, 'free protons' AS b, 'no electrons' AS c, 'high density' AS d, 'A' AS k
    UNION ALL SELECT 'Which of these is an alloy?' AS q, 'Pure copper' AS a, 'Pure iron' AS b, 'Brass' AS c, 'Pure gold' AS d, 'C' AS k
    UNION ALL SELECT 'Brass is an alloy of copper and' AS q, 'tin' AS a, 'zinc' AS b, 'lead' AS c, 'nickel' AS d, 'B' AS k
    UNION ALL SELECT 'Stainless steel is an alloy of iron and' AS q, 'zinc' AS a, 'carbon' AS b, 'chromium' AS c, 'copper' AS d, 'C' AS k
    UNION ALL SELECT 'Solder is an alloy of tin and' AS q, 'copper' AS a, 'zinc' AS b, 'aluminium' AS c, 'lead' AS d, 'D' AS k
    UNION ALL SELECT 'Type D cast iron contains the element' AS q, 'nickel' AS a, 'titanium' AS b, 'manganese' AS c, 'silicon' AS d, 'C' AS k
    UNION ALL SELECT 'An alloy is made by melting the constituents together because metals' AS q, 'cannot be mixed in the solid state' AS a, 'melt at the same temperature' AS b, 'dissolve only in acid' AS c, 'react chemically only when molten' AS d, 'D' AS k
  ) t ON 1 = 1
 WHERE s.subject_code = 'CHM201'
   AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.subject_id = s.id);

-- ------------------------------------------------------------
-- Verification: expect 4 subjects and 497 questions.
-- Verification: expect 4 subjects and 497 questions.
SELECT s.subject_code, s.subject_name, COUNT(q.id) AS questions
  FROM subjects s
  LEFT JOIN questions q ON q.subject_id = s.id AND q.is_active = 1
 WHERE s.subject_code IN ('ENG201','MTH201','PHY201','CHM201')
 GROUP BY s.id, s.subject_code, s.subject_name
 ORDER BY s.subject_code;

SELECT COUNT(*) AS total_questions FROM questions;
